import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.DDY-poMm.js";const u=JSON.parse('{"title":"App Releases","description":"","frontmatter":{},"headers":[],"relativePath":"guide/app-release.md","filePath":"guide/app-release.md","lastUpdated":1790683574000}'),n={name:"guide/app-release.md"};function r(i,e,d,l,p,h){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="app-releases" tabindex="-1">App Releases <a class="header-anchor" href="#app-releases" aria-label="Permalink to &quot;App Releases&quot;">​</a></h1><p>How do users who already have the app installed find out about a new version?</p><p>Since v1.0.2, the app has built-in <strong>version checking</strong>: on every launch it asks the platform for the latest version, shows a prompt if it is newer, and users can tap update to download and install inside the app — no need to find it in the download center.</p><p>This page covers <strong>what operators need to do in the admin console</strong>. Building and uploading the package is technical work done by your technical team.</p><h2 id="where-to-configure" tabindex="-1">Where to configure <a class="header-anchor" href="#where-to-configure" aria-label="Permalink to &quot;Where to configure&quot;">​</a></h2><p>&quot;Basic Configuration → App Version Update&quot; in the admin console.</p><div class="danger custom-block"><p class="custom-block-title">Super-admin only</p><p>Only a super administrator can change this setting. See &quot;Force update&quot; below for why.</p></div><h2 id="six-fields" tabindex="-1">Six fields <a class="header-anchor" href="#six-fields" aria-label="Permalink to &quot;Six fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>What to enter</th></tr></thead><tbody><tr><td><strong>Update check master switch</strong></td><td>On. When off, the app does not check for new versions at all</td></tr><tr><td><strong>Latest version code (versionCode)</strong></td><td>The integer version code given by your technical team; it increases with every release</td></tr><tr><td><strong>Latest version name</strong></td><td>The version number shown to users, e.g. <code>1.0.4</code></td></tr><tr><td><strong>Force-update version code</strong></td><td><strong>Normally always 0</strong> (no forced update)</td></tr><tr><td><strong>APK download URL</strong></td><td>The full download link given by your technical team; must start with <code>https://</code></td></tr><tr><td><strong>Update notes</strong></td><td>Text users see in the prompt, one item per line</td></tr></tbody></table><h2 id="what-users-see" tabindex="-1">What users see <a class="header-anchor" href="#what-users-see" aria-label="Permalink to &quot;What users see&quot;">​</a></h2><ul><li><strong>Normal update</strong>: the prompt shows the version number and update notes and can be dismissed with &quot;Later&quot;. Once dismissed, <strong>it won&#39;t show again that day</strong> and reminds once more the next day</li><li>Tapping &quot;Update now&quot;: the app shows a download progress bar, then opens the system installer when done</li><li>On first install, Android asks the user to allow &quot;Install unknown apps&quot; — this is a system step and cannot be skipped</li></ul><h2 id="force-update" tabindex="-1">Force update <a class="header-anchor" href="#force-update" aria-label="Permalink to &quot;Force update&quot;">​</a></h2><p>Once &quot;Force-update version code&quot; is set to M, users with a version code below M see an update prompt that <strong>cannot be dismissed</strong> — they cannot use the app without updating.</p><div class="danger custom-block"><p class="custom-block-title">This is equivalent to shutting service off for those users</p><p>Use it only when a version has a serious problem (e.g. wrong balances shown, unable to place orders). A wrong value locks <strong>every user</strong> out.</p><p>Two safeguards are built in:</p><ol><li>On save, the force-update version code must not be greater than the latest version code</li><li>Entering a value greater than 0 requires a second confirmation</li></ol><p>But neither stops &quot;a valid but too-large value&quot;. Make sure before saving.</p></div><h2 id="correct-order-when-releasing" tabindex="-1">Correct order when releasing <a class="header-anchor" href="#correct-order-when-releasing" aria-label="Permalink to &quot;Correct order when releasing&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Technical team builds and uploads the package</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Technical team confirms the download link works</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Operator fills in and saves the configuration   ← users are prompted only after this step</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Verify yourself: open an old version of the app and confirm the prompt appears</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Don&#39;t reverse the order</p><p><strong>Confirm the download link works first, then change the admin configuration.</strong> Otherwise users get an update prompt but the download fails.</p></div><h2 id="how-this-differs-from-download-links" tabindex="-1">How this differs from &quot;Download links&quot; <a class="header-anchor" href="#how-this-differs-from-download-links" aria-label="Permalink to &quot;How this differs from &quot;Download links&quot;&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Download links</th><th>App version update</th></tr></thead><tbody><tr><td>For whom</td><td><strong>New users who haven&#39;t installed the app</strong></td><td><strong>Existing users who have the app installed</strong></td></tr><tr><td>Where it appears</td><td>The download center page on the user side</td><td>The update prompt when the app launches</td></tr></tbody></table><p>The two are independent, but we recommend <strong>pointing them at the same version</strong>; otherwise new users install an old package and are immediately prompted to update.</p>`,20)])])}const g=t(n,[["render",r]]);export{u as __pageData,g as default};
